// Project emblem colours: three related colours from the project name, or around the project's chosen tint.
// Static art (Abhay 11-22: "autogenerated 3 color orb ... no motion"; spinners are only for running chats).

export const hashName = s => { let h = 2166136261; for (const c of s) h = Math.imul(h ^ c.charCodeAt(0), 16777619); return h >>> 0 }
export const rng = seed => () => ((seed = (Math.imul(seed ^ (seed >>> 15), 2246822507) + 0x9e3779b9) >>> 0) / 4294967296)

/** hue of each pastel in the colour menu */
export const TINT_HUE = { rose: 345, peach: 25, butter: 50, mint: 145, sky: 210, lilac: 260 }

/** three hsl() colours, stepping 28-68 degrees round the wheel from a base hue */
export function orbPalette(name, { tint = 'auto', light = false } = {}) {
  const r = rng(hashName(name))
  const seeded = r() * 360, step = 28 + r() * 40
  const h = TINT_HUE[tint] ?? seeded
  const L = light ? [62, 70, 78] : [66, 74, 82], S = light ? 70 : 78
  return [0, 1, 2].map(i => `hsl(${Math.round((h + i * step) % 360)} ${S}% ${L[i]}%)`)
}
